from sklearn.feature_extraction import FeatureHasher

class FeatureExplainer(FeatureHasher):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.explain_dict = {}

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        if not hasattr(X, 'dtype'):
            raise AttributeError('input should be a numpy array')
        if len(np.unique(X)) > 0:
            self.explain_dict = dict([(i,f) for i, f in enumerate(self.classes_)])
            return self.transform(X)
        else:
            raise ValueError("input should have at least one unique value")

    def explain_output(self, index, output):
        return self.explain_dict[index]

fea_explainer = FeatureExplainer()
print(fea_explainer.fit_transform(['Mast cells', 'are cellular components of the innate immune response and are important to wound healing and defense against pathogens via an inflammatory response.'], ['Prostaglandins']))
